#!/usr/bin/env node
"use strict";

// Derives src/search/stem/{it,en}*.js from the pinned @nlpjs devDependencies with mechanical
// edits only (docs/plan-1.0.md WP1, B-8). Re-run after bumping @nlpjs/lang-it or
// @nlpjs/lang-en-min, then `npx biome lint --write src/search/stem`,
// `npx biome format --write src/search/stem` and `npm test` (test/stem-parity.test.js pins
// zero disagreements with upstream).
//
//   node scripts/vendor-stemmers.js
//
// Each upstream stemmer is one 1,300-1,450 line class generated by the Snowball compiler, above
// the 800-line cap (Q-1). It is split by routine group into object-literal mixins assigned onto
// the class prototype: <lang>-tables.js (Among tables and groupings), <lang>-regions.js
// (prelude, region marking, postlude, helpers), <lang>-suffixes.js (the suffix steps), and
// <lang>.js (constructor and innerStem).

const fs = require("node:fs");
const path = require("node:path");

const REPO = path.join(__dirname, "..");
const MODULES = path.join(REPO, "node_modules");
const OUT = path.join(REPO, "src", "search", "stem");

const SPECS = [
  {
    code: "it",
    className: "StemmerIt",
    package: "@nlpjs/lang-it",
    file: "stemmer-it.js",
    algorithm: "Snowball Italian",
    groups: {
      regions: ["r_prelude", "r_mark_regions", "r_postlude", "r_RV"],
      suffixes: ["r_attached_pronoun", "r_standard_suffix", "r_verb_suffix", "r_vowel_suffix"],
    },
  },
  {
    code: "en",
    className: "StemmerEn",
    package: "@nlpjs/lang-en-min",
    file: "stemmer-en.js",
    algorithm: "Snowball English (Porter2)",
    groups: {
      regions: [
        "r_prelude",
        "r_mark_regions",
        "r_shortv",
        "r_R1",
        "r_R2",
        "r_postlude",
        "r_exception2",
        "r_exception1",
      ],
      suffixes: [
        "r_Step_1a",
        "r_Step_1b",
        "r_Step_1c",
        "r_Step_2",
        "r_Step_3",
        "r_Step_4",
        "r_Step_5",
      ],
    },
  },
];

// Labels that share a name with their guard variable (`lab9: while (lab9 == true)`) are renamed
// to `label9`; break/continue targets follow. Variable references are untouched.
function renameLabels(body) {
  return body
    .replace(/^(\s*)lab(\d+):(\s*(?:while|do|for)\b)/gm, "$1label$2:$3")
    .replace(/\b(break|continue) lab(\d+);/g, "$1 label$2;");
}

// `let v_N;` declared at method top and assigned exactly once, in the same scope, with no read
// before the assignment, becomes `const v_N = ...;` at the assignment (lint/style/useConst).
function hoistSingleAssignments(body) {
  const lines = body.split("\n");
  const removed = new Set();
  lines.forEach((line, index) => {
    const declaration = /^(\s*)let (v_\d+|among_var);$/.exec(line);
    if (!declaration) return;
    const indent = declaration[1];
    const name = declaration[2];
    const closing = `${indent.slice(2)}}`;
    let end = index + 1;
    while (end < lines.length && lines[end] !== closing) end += 1;
    const assignment = new RegExp(`^(\\s*)${name} = `);
    const reference = new RegExp(`\\b${name}\\b`);
    const assignments = [];
    for (let cursor = index + 1; cursor < end; cursor += 1) {
      if (assignment.test(lines[cursor])) assignments.push(cursor);
    }
    if (assignments.length !== 1) return;
    const target = assignments[0];
    if (assignment.exec(lines[target])[1] !== indent) return;
    for (let cursor = index + 1; cursor < target; cursor += 1) {
      if (reference.test(lines[cursor])) return;
    }
    lines[target] = lines[target].replace(assignment, `${indent}const ${name} = `);
    removed.add(index);
  });
  return lines.filter((_, index) => !removed.has(index)).join("\n");
}

// Class methods at two-space indentation, keyed by name, in source order.
function extractMethods(classBody) {
  const lines = classBody.split("\n");
  const methods = new Map();
  for (let index = 0; index < lines.length; index += 1) {
    const match = /^ {2}([A-Za-z_][A-Za-z0-9_]*)\(\) \{$/.exec(lines[index]);
    if (!match) continue;
    let end = index + 1;
    while (end < lines.length && lines[end] !== "  }") end += 1;
    methods.set(match[1], lines.slice(index, end + 1).join("\n"));
    index = end;
  }
  return methods;
}

function fileHeader(spec, license, version, role) {
  return [
    license,
    "",
    `// Provenance: derived from ${spec.package} ${version}, src/${spec.file} (MIT,`,
    "// header above), itself generated by the Snowball compiler from the",
    `// ${spec.algorithm} stemming algorithm; this file holds ${role}.`,
    "// Mechanical changes only (scripts/vendor-stemmers.js): the class is split",
    "// by routine group to stay under the 800-line cap, local requires replace",
    "// @nlpjs/core, no container or tokenizer plumbing, strict equality,",
    "// block-scoped and const declarations, labels renamed apart from their",
    "// guard variables, Biome formatting. test/stem-parity.test.js pins zero",
    "// disagreements with the upstream package.",
    '"use strict";',
    "",
  ].join("\n");
}

function derive(spec) {
  const pkg = JSON.parse(fs.readFileSync(path.join(MODULES, spec.package, "package.json"), "utf8"));
  const text = fs.readFileSync(path.join(MODULES, spec.package, "src", spec.file), "utf8");
  const licenseEnd = text.indexOf("*/") + 2;
  const license = text.slice(0, licenseEnd);
  let body = text.slice(licenseEnd);
  body = body.replace(/const \{ Among, BaseStemmer \} = require\('@nlpjs\/core'\);\n/, "");
  body = body.replace(/const TokenizerEn = require\('\.\/tokenizer-en'\);\n/, "");
  body = body.replace(/\/\* eslint-disable \*\/\n/, "");
  // Methods that only serve the nlp.js container: tokenizer lookup, state copy.
  body = body.replace(/\n {2}getTokenizer\(\) \{[\s\S]*?\n {2}\}\n/, "\n");
  body = body.replace(/\n {2}copy_from\(other\) \{[\s\S]*?\n {2}\}\n/, "\n");
  body = body.replace(
    /constructor\(container\) \{\n {4}super\(container\);\n/,
    "constructor() {\n    super();\n",
  );
  body = body.replace(/ == /g, " === ").replace(/ != /g, " !== ");
  body = body.replace(/\bvar c = /g, "const c = ").replace(/\bvar /g, "let ");
  body = body.replace(new RegExp(`\\b${spec.className}\\.`, "g"), "tables.");
  body = renameLabels(body);
  body = hoistSingleAssignments(body);

  const classStart = body.indexOf(`class ${spec.className} extends BaseStemmer {`);
  const classEnd = body.indexOf("\n}\n", classStart) + 3;
  const classBody = body.slice(classStart, classEnd);
  // Upstream also creates an unused static `methodObject` instance; dropped.
  const tablesBody = body
    .slice(classEnd)
    .replace(new RegExp(`module\\.exports = ${spec.className};\\s*$`), "")
    .replace(new RegExp(`tables\\.methodObject = new ${spec.className}\\(\\);\\n`), "")
    .trim();
  const methods = extractMethods(classBody);
  const grouped = new Set(Object.values(spec.groups).flat());
  const classMethods = Array.from(methods.keys()).filter((name) => !grouped.has(name));
  Object.values(spec.groups)
    .flat()
    .forEach((name) => {
      if (!methods.has(name)) {
        throw new Error(`${spec.file}: method ${name} not found`);
      }
    });
  const header = (role) => fileHeader(spec, license, pkg.version, role);
  const written = [];
  const write = (name, content) => {
    fs.writeFileSync(path.join(OUT, name), content);
    written.push({ file: name, lines: content.split("\n").length - 1 });
  };

  write(
    `${spec.code}-tables.js`,
    `${header("the suffix tables and character groupings")}const Among = require("./among");\n\nconst tables = {};\n\n${tablesBody}\n\nmodule.exports = tables;\n`,
  );
  Object.entries(spec.groups).forEach(([group, names]) => {
    const role =
      group === "regions"
        ? "the prelude, region marking and helper routines"
        : "the suffix removal steps";
    const content = names.map((name) => `${methods.get(name)},`).join("\n\n");
    write(
      `${spec.code}-${group}.js`,
      `${header(role)}const tables = require("./${spec.code}-tables");\n\nmodule.exports = {\n${content}\n};\n`,
    );
  });
  const classContent = classMethods.map((name) => methods.get(name)).join("\n\n");
  const mixins = Object.keys(spec.groups)
    .map((group) => `  require("./${spec.code}-${group}"),`)
    .join("\n");
  const classRequires = classContent.includes("tables.")
    ? `const BaseStemmer = require("./base-stemmer");\nconst tables = require("./${spec.code}-tables");\n`
    : `const BaseStemmer = require("./base-stemmer");\n`;
  write(
    `${spec.code}.js`,
    `${header("the class with its entry point")}${classRequires}\nclass ${spec.className} extends BaseStemmer {\n${classContent}\n}\n\nObject.assign(\n  ${spec.className}.prototype,\n${mixins}\n);\n\nmodule.exports = ${spec.className};\n`,
  );
  return { package: spec.package, version: pkg.version, written };
}

if (require.main === module) {
  SPECS.forEach((spec) => {
    const result = derive(spec);
    process.stdout.write(`${JSON.stringify(result)}\n`);
  });
}

module.exports = { SPECS, derive };
